from pathlib import Path

def r(path, old, new):
    p=Path(path); t=p.read_text()
    if t.count(old)!=1: raise SystemExit(f'{path}: expected 1 match, got {t.count(old)}')
    p.write_text(t.replace(old,new))

# Runtime worker override is the authoritative canary eligibility layer.
r('community/workers/runtime-worker-overrides.yaml', '''  documentation:\n    preferred_implementations:\n      - claude-haiku-4-5\n      - gemini-3.6-flash\n      - gpt-5.6-luna\n      - claude-sonnet-5\n      - gpt-5.6-sol\n    fallbacks:\n      - gemini-3.6-flash\n      - gpt-5.6-luna\n      - claude-sonnet-5\n      - gpt-5.6-sol\n''', '''  documentation:\n    preferred_implementations:\n      - gemini-3.5-flash-lite\n      - claude-haiku-4-5\n      - gemini-3.6-flash\n      - gpt-5.6-luna\n      - claude-sonnet-5\n      - gpt-5.6-sol\n    fallbacks:\n      - claude-haiku-4-5\n      - gpt-5.6-luna\n      - claude-sonnet-5\n      - gpt-5.6-sol\n''')

# Stronger verifier topology: Sonnet verifies Flash-Lite primary; Gemini verifies Haiku fallback.
r('policy/routing/routing.yaml', '''    verifier:\n      agent: claude\n      model: claude-haiku-4-5\n      profile: luna\n      reasoning: default\n      purpose: provider-diverse pointwise validation of the primary Flash-Lite route\n''', '''    verifier:\n      agent: claude\n      model: claude-sonnet-5\n      profile: sol\n      reasoning: medium\n      purpose: provider-diverse semantic verification of the primary Flash-Lite route\n''')

# Rewrite guarded fallback tests around the new executor topology.
p=Path('tests/test_guarded_canary_fallback.py'); t=p.read_text()
t=t.replace('''def anthropic_provider_failure() -> dict:\n    return {\n        "type": "error",\n        "error": {"type": "rate_limit_error", "message": "provider unavailable"},\n    }\n\n\ndef anthropic_model_failure() -> dict:\n    return {\n        "type": "error",\n        "error": {"type": "not_found_error", "message": "model unavailable"},\n    }\n\n\ndef gemini_success() -> dict:\n''', '''def anthropic_success() -> dict:\n    return {\n        "id": "msg_fallback",\n        "model": "claude-haiku-4-5",\n        "content": [{"type": "text", "text": "label_a\\nlabel_b"}],\n    }\n\n\ndef anthropic_transient_failure() -> dict:\n    return {\n        "type": "error",\n        "error": {"type": "api_error", "message": "try later"},\n    }\n\n\ndef gemini_provider_failure() -> dict:\n    return {"error": {"status": "RESOURCE_EXHAUSTED", "message": "provider unavailable"}}\n\n\ndef gemini_model_failure() -> dict:\n    return {"error": {"status": "NOT_FOUND", "message": "model unavailable"}}\n\n\ndef gemini_success() -> dict:\n''')

start=t.index('def test_provider_failure_redispatches_to_declared_fallback_with_new_verifier')
end=t.index('\ndef test_guarded_fallback_refuses_non_high_volume_task', start) if '\ndef test_guarded_fallback_refuses_non_high_volume_task' in t[start:] else len(t)
prefix=t[:start]; suffix=t[end:]
new_tests='''def test_provider_failure_redispatches_to_declared_fallback_with_new_verifier(tmp_path: Path) -> None:\n    anthropic_calls: list[dict] = []\n    google_calls: list[dict] = []\n    openai_calls: list[dict] = []\n    outcome = execute_guarded_canary(\n        engine(),\n        task(),\n        {\n            "google": connection("google", google_calls, status=429, payload=gemini_provider_failure()),\n            "anthropic": connection("anthropic", anthropic_calls, status=200, payload=anthropic_success()),\n            "openai": connection("openai", openai_calls, status=200, payload={}),\n        },\n        artifact_root=tmp_path,\n    )\n\n    assert outcome.status == "fallback_executed"\n    assert outcome.execution_succeeded is True\n    assert outcome.fallback_trigger_scope == "provider"\n    assert outcome.primary_dispatch.selected_implementation.model == "gemini-3.5-flash-lite"\n    assert outcome.primary_dispatch.verification.implementation.model == "claude-sonnet-5"\n    assert outcome.primary_dispatch.fallback_implementation is not None\n    assert outcome.primary_dispatch.fallback_implementation.model == "claude-haiku-4-5"\n    assert outcome.fallback_dispatch is not None\n    assert outcome.fallback_dispatch.selected_implementation.model == "claude-haiku-4-5"\n    assert outcome.fallback_dispatch.verification.implementation.model == "gpt-5.6-sol"\n    assert outcome.fallback_dispatch.verification.implementation.model != outcome.primary_dispatch.verification.implementation.model\n    assert outcome.primary_attempts == 1\n    assert outcome.fallback_attempts == 1\n    assert len(google_calls) == 1\n    assert len(anthropic_calls) == 1\n    assert openai_calls == []\n\n\ndef test_model_failure_redispatches_with_failed_model_blocked(tmp_path: Path) -> None:\n    anthropic_calls: list[dict] = []\n    google_calls: list[dict] = []\n    outcome = execute_guarded_canary(\n        engine(),\n        task(),\n        {\n            "google": connection("google", google_calls, status=404, payload=gemini_model_failure()),\n            "anthropic": connection("anthropic", anthropic_calls, status=200, payload=anthropic_success()),\n        },\n        artifact_root=tmp_path,\n    )\n\n    assert outcome.status == "fallback_executed"\n    assert outcome.fallback_trigger_scope == "model"\n    assert outcome.fallback_dispatch is not None\n    assert outcome.fallback_dispatch.selected_implementation.model == "claude-haiku-4-5"\n    assert outcome.fallback_dispatch.verification.implementation.model == "gemini-3.6-flash"\n    assert len(google_calls) == 1\n    assert len(anthropic_calls) == 1\n\n\ndef test_transient_failure_retries_same_dispatch_without_fallback(tmp_path: Path) -> None:\n    google_calls: list[dict] = []\n    anthropic_calls: list[dict] = []\n    outcome = execute_guarded_canary(\n        engine(),\n        task(),\n        {\n            "google": connection("google", google_calls, fail_transport=True),\n            "anthropic": connection("anthropic", anthropic_calls, status=200, payload=anthropic_success()),\n        },\n        artifact_root=tmp_path,\n        sleeper=lambda _: None,\n        random_source=lambda: 0.5,\n    )\n\n    assert outcome.status == "execution_failed"\n    assert outcome.primary_response.failure is not None\n    assert outcome.primary_response.failure.scope == "transient"\n    assert outcome.primary_attempts == 2\n    assert outcome.primary_retry_delays_seconds == (0.5,)\n    assert outcome.fallback_dispatch is None\n    assert len(google_calls) == 2\n    assert anthropic_calls == []\n\n\ndef test_request_failure_does_not_retry_or_fallback(tmp_path: Path) -> None:\n    google_calls: list[dict] = []\n    anthropic_calls: list[dict] = []\n    outcome = execute_guarded_canary(\n        engine(),\n        task(),\n        {\n            "google": connection(\n                "google", google_calls, status=400,\n                payload={"error": {"status": "INVALID_ARGUMENT", "message": "bad request"}},\n            ),\n            "anthropic": connection("anthropic", anthropic_calls, status=200, payload=anthropic_success()),\n        },\n        artifact_root=tmp_path,\n    )\n\n    assert outcome.status == "execution_failed"\n    assert outcome.primary_response.failure is not None\n    assert outcome.primary_response.failure.scope == "request"\n    assert outcome.primary_attempts == 1\n    assert outcome.fallback_dispatch is None\n    assert len(google_calls) == 1\n    assert anthropic_calls == []\n\n\ndef test_failed_fallback_does_not_chain_to_a_third_provider(tmp_path: Path) -> None:\n    google_calls: list[dict] = []\n    anthropic_calls: list[dict] = []\n    openai_calls: list[dict] = []\n    outcome = execute_guarded_canary(\n        engine(),\n        task(),\n        {\n            "google": connection("google", google_calls, status=429, payload=gemini_provider_failure()),\n            "anthropic": connection("anthropic", anthropic_calls, status=503, payload=anthropic_transient_failure()),\n            "openai": connection("openai", openai_calls, status=200, payload={}),\n        },\n        artifact_root=tmp_path,\n        sleeper=lambda _: None,\n        random_source=lambda: 0.5,\n    )\n\n    assert outcome.status == "execution_failed"\n    assert outcome.fallback_dispatch is not None\n    assert outcome.fallback_response is not None\n    assert outcome.fallback_response.failure is not None\n    assert outcome.primary_attempts == 1\n    assert outcome.fallback_attempts == 2\n    assert outcome.fallback_retry_delays_seconds == (0.5,)\n    assert len(google_calls) == 1\n    assert len(anthropic_calls) == 2\n    assert openai_calls == []\n\n'''
p.write_text(prefix+new_tests+suffix)

# Reconcile independent-verification conformance tests to new primary/fallback/verifier topology.
p=Path('tests/test_live_independent_verification.py'); t=p.read_text()
t=t.replace('''def test_primary_canary_uses_provider_diverse_gemini_verifier() -> None:\n    dispatch = engine().dispatch(task())\n    assert dispatch.selected_implementation.model == "claude-haiku-4-5"\n    assert dispatch.selected_implementation.provider_family == "anthropic"\n    assert dispatch.verification.implementation.model == "gemini-3.6-flash"\n    assert dispatch.verification.implementation.provider_family == "google"\n    assert dispatch.verification.implementation.reasoning == "medium"\n''', '''def test_primary_canary_uses_provider_diverse_sonnet_verifier() -> None:\n    dispatch = engine().dispatch(task())\n    assert dispatch.selected_implementation.model == "gemini-3.5-flash-lite"\n    assert dispatch.selected_implementation.provider_family == "google"\n    assert dispatch.verification.implementation.model == "claude-sonnet-5"\n    assert dispatch.verification.implementation.provider_family == "anthropic"\n    assert dispatch.verification.implementation.reasoning == "medium"\n''')
t=t.replace('''def test_model_scoped_fallback_gets_fresh_anthropic_verifier() -> None:\n    runtime = engine()\n    primary = runtime.dispatch(task())\n    fallback = runtime.dispatch(task(blocked_models=["claude-haiku-4-5"]))\n    assert fallback.selected_implementation.model == "gemini-3.6-flash"\n    assert fallback.verification.implementation.model == "claude-sonnet-5"\n    assert fallback.verification.implementation.provider_family == "anthropic"\n    assert fallback.verification.implementation.model != primary.verification.implementation.model\n''', '''def test_model_scoped_fallback_gets_fresh_gemini_verifier() -> None:\n    runtime = engine()\n    primary = runtime.dispatch(task())\n    fallback = runtime.dispatch(task(blocked_models=["gemini-3.5-flash-lite"]))\n    assert fallback.selected_implementation.model == "claude-haiku-4-5"\n    assert fallback.verification.implementation.model == "gemini-3.6-flash"\n    assert fallback.verification.implementation.provider_family == "google"\n    assert fallback.verification.implementation.model != primary.verification.implementation.model\n''')
t=t.replace('''    fallback = runtime.dispatch(task(blocked_providers=["anthropic"]))\n    assert fallback.selected_implementation.model == "gemini-3.6-flash"\n''', '''    fallback = runtime.dispatch(task(blocked_providers=["google"]))\n    assert fallback.selected_implementation.model == "claude-haiku-4-5"\n''')
t=t.replace('''def test_primary_live_verifier_is_blinded_and_uses_google_structured_output(tmp_path: Path) -> None:\n    runtime = engine()\n    dispatch = runtime.dispatch(task())\n    calls: list[dict] = []\n    result = execute_live_verification(\n        runtime,\n        dispatch,\n        success_response(dispatch, write_output(tmp_path)),\n        {"google": connection("google", calls, google_payload(decision()))},\n        artifact_root=tmp_path,\n    )\n\n    assert result.status == "passed"\n    assert result.verifier_model == "gemini-3.6-flash"\n    body = calls[0]["body"]\n    assert body["model"] == "gemini-3.6-flash"\n    assert body["generation_config"]["thinking_level"] == "medium"\n    assert body["response_format"]["type"] == "text"\n    assert body["response_format"]["mime_type"] == "application/json"\n    serialized = json.dumps(body)\n    assert "claude-haiku-4-5" not in serialized\n    assert "anthropic" not in serialized.lower()\n    assert "fallback" not in serialized.lower()\n    assert "runtime-telemetry" not in serialized.lower()\n    assert "untrusted data" in serialized.lower()\n''', '''def test_primary_live_verifier_is_blinded_and_uses_sonnet_structured_output(tmp_path: Path) -> None:\n    runtime = engine()\n    dispatch = runtime.dispatch(task())\n    calls: list[dict] = []\n    result = execute_live_verification(\n        runtime,\n        dispatch,\n        success_response(dispatch, write_output(tmp_path)),\n        {"anthropic": connection("anthropic", calls, anthropic_payload(decision()))},\n        artifact_root=tmp_path,\n    )\n\n    assert result.status == "passed"\n    assert result.verifier_model == "claude-sonnet-5"\n    body = calls[0]["body"]\n    assert body["model"] == "claude-sonnet-5"\n    assert body["output_config"]["effort"] == "medium"\n    assert body["output_config"]["format"]["type"] == "json_schema"\n    serialized = json.dumps(body)\n    assert "gemini-3.5-flash-lite" not in serialized\n    assert "google" not in serialized.lower()\n    assert "fallback" not in serialized.lower()\n    assert "runtime-telemetry" not in serialized.lower()\n    assert "untrusted data" in serialized.lower()\n''')
t=t.replace('''def test_model_fallback_uses_assigned_sonnet_verifier_and_effort(tmp_path: Path) -> None:\n    runtime = engine()\n    dispatch = runtime.dispatch(task(blocked_models=["claude-haiku-4-5"]))\n    calls: list[dict] = []\n    result = execute_live_verification(\n        runtime,\n        dispatch,\n        success_response(dispatch, write_output(tmp_path)),\n        {"anthropic": connection("anthropic", calls, anthropic_payload(decision()))},\n        artifact_root=tmp_path,\n    )\n\n    assert result.status == "passed"\n    assert result.verifier_model == "claude-sonnet-5"\n    body = calls[0]["body"]\n    assert body["model"] == "claude-sonnet-5"\n    assert body["output_config"]["effort"] == "medium"\n    assert body["output_config"]["format"]["type"] == "json_schema"\n    serialized = json.dumps(body)\n    assert "gemini-3.6-flash" not in serialized\n    assert "google" not in serialized.lower()\n''', '''def test_model_fallback_uses_assigned_gemini_verifier_and_effort(tmp_path: Path) -> None:\n    runtime = engine()\n    dispatch = runtime.dispatch(task(blocked_models=["gemini-3.5-flash-lite"]))\n    calls: list[dict] = []\n    result = execute_live_verification(\n        runtime,\n        dispatch,\n        success_response(dispatch, write_output(tmp_path)),\n        {"google": connection("google", calls, google_payload(decision()))},\n        artifact_root=tmp_path,\n    )\n\n    assert result.status == "passed"\n    assert result.verifier_model == "gemini-3.6-flash"\n    body = calls[0]["body"]\n    assert body["model"] == "gemini-3.6-flash"\n    assert body["generation_config"]["thinking_level"] == "medium"\n    assert body["response_format"]["type"] == "text"\n    serialized = json.dumps(body)\n    assert "claude-haiku-4-5" not in serialized\n    assert "anthropic" not in serialized.lower()\n''')
t=t.replace('dispatch = runtime.dispatch(task(blocked_providers=["anthropic"]))','dispatch = runtime.dispatch(task(blocked_providers=["google"]))')
p.write_text(t)
